import Apps from "./Apps";
import Funds from "./Funds";
import Holdings from "./Holdings";
import Orders from "./Orders";
import Positions from "./Positions";
import Summary from "./Summary";
import Watchlist from "./WatchList";

const Dashboard = () => {
    return (
        <div className="dashboard-container">
            <Watchlist/>
            <div className="content">
                <Routes>
                    <Routes exact path="/" element={<Summary />} />
                    <Routes path="/orders" element={<Orders />} />
                    <Routes path="/holdings" element={<Holdings />} />
                    <Routes path="/positons" element={<Positions />} />
                    <Routes path="./funds" element={<Funds />} />
                    <Routes path="./apps" element={<Apps />} />
                </Routes>
        </div>
        </div>

    );
}
